import {recordRow} from './record-row.js';
import {calendarStart,calendarNext,calendarLabel} from './calendar-periods.js';
import {statsPage,bindStats} from './stats.js';
import {startAuth,isUnlocked,assertSession,sessionId,lock,updateProfileName,withSystemPrompt,secureRead,secureWriteMany,secureDelete} from './auth.js';
import {qrPage,bindQr,stopQr} from './qr-transfer.js';
import {analysisPage,bindAnalysis} from './analysis.js';
import {reminderSettings,bindReminders,initReminders,clearReminderMessages,resumeReminders,pauseReminderMessages,notificationPage} from './reminders.js';
import {load,save,merge,readExcel,writeExcel,key,monthOf,norm} from './ledger.js';
import {saveGeneratedExport,loadGeneratedExport,clearGeneratedExport,deduplicated} from './ledger.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:2,minimumFractionDigits:0}).format((n||0)/100);
const date=t=>new Date(t).toLocaleDateString('en-IN',{day:'numeric',month:'short'}),sum=a=>a.reduce((n,t)=>n+t.amount,0),today=new Date(),todayKey=today.toDateString();
let state,page='home',selected=monthOf(Date.now()),query='',type='ALL',account='ALL',busy=false,pendingImportFile=null,historyFilter=null,qrIntent=null,historyUnit='monthly',historyAt=Date.now();
const prefs=JSON.parse(localStorage.getItem('nidhi-prefs')||'{"theme":"light","accent":"#28634e","wallpaper":"mist","name":""}');
function appearance(){document.body.classList.toggle('dark',prefs.theme==='dark'||prefs.theme==='system'&&matchMedia('(prefers-color-scheme: dark)').matches);document.documentElement.style.setProperty('--accent',prefs.accent);document.body.dataset.wallpaper=prefs.wallpaper;localStorage.setItem('nidhi-prefs',JSON.stringify(prefs));$('.avatar').textContent=(prefs.name||'N')[0].toUpperCase()}
appearance();$('#month').value=selected;
localStorage.removeItem('nidhi-google-public-config');localStorage.removeItem('nidhi-last-backup');
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4500)}
function modal(body,actions,onSubmit){assertSession();$('#modal-body').innerHTML=body;$('#modal-actions').innerHTML=actions||'';$('#modal-error').textContent='';$('#modal-form').onsubmit=async e=>{e.preventDefault();if(!onSubmit)return;const btn=e.submitter;if(btn)btn.disabled=true;try{await onSubmit(new FormData(e.target))}catch(e){$('#modal-error').textContent=e.message}finally{if(btn)btn.disabled=false}};$('#modal').showModal()}
const close=()=>$('#modal').close();$('#close-modal').onclick=close;
const action=(label='Save')=>`<button type="button" class="secondary" data-close>Cancel</button><button class="primary" type="submit">${label}</button>`;
async function commit(next){const id=sessionId();assertSession(id);await save(next);assertSession(id);state=next;render()}
async function commitQrBatch(next,receipts){const id=sessionId();assertSession(id);await secureWriteMany({'ledger':{...next,updated:Date.now()},'qr-receipts':receipts});assertSession(id);state=next;if(page!=='qr')render()}
function txMonth(){return state.transactions.filter(t=>monthOf(t.dateTime)===selected)}
function calc(){const today=new Date(),todayKey=today.toDateString();const tx=txMonth(),income=sum(tx.filter(t=>t.type==='INCOME')),expense=sum(tx.filter(t=>t.type==='EXPENSE'));const commitments=state.budget.commitments.filter(c=>c.month===selected&&(c.enabled||c.paidAt>0));const keys=new Set(tx.map(key));const linked=new Set(commitments.filter(c=>c.paymentKey&&keys.has(c.paymentKey)).map(c=>c.paymentKey));const paid=tx.filter(t=>linked.has(key(t)));const reserved=commitments.reduce((n,c)=>n+c.amount,0);const discretionary=expense-sum(paid);const plan=state.budget.plans.find(p=>p.month===selected);const regular=(state.budget.incomeSources||[]).filter(x=>x.month===selected&&x.enabled);const base=Number.isSafeInteger(plan?.income)?plan.income:regular.length?regular.reduce((n,x)=>n+x.amount,0):income;const [y,m]=selected.split('-').map(Number);const days=new Date(y,m,0).getDate(),day=selected===monthOf(Date.now())?today.getDate():selected<monthOf(Date.now())?days:1;const spentToday=sum(tx.filter(t=>t.type==='EXPENSE'&&!linked.has(key(t))&&new Date(t.dateTime).toDateString()===todayKey));const remaining=base-reserved-discretionary;const limit=Math.max(0,Math.floor((base-reserved-(discretionary-spentToday))/(days-day+1)));return {tx,income,expense,reserved,remaining,limit,spentToday,balance:income-expense,days,base,day}}
const titles={notifications:['Notifications','','',''],home:['Overview','MAKE ROOM FOR WHAT MATTERS','Your money, in balance.','A clear view of today. A thoughtful plan for tomorrow.'],history:['Transactions','EVERY LITTLE DETAIL','Your money story.','All your income and expenses, together in one place.'],plan:['Monthly plan','A LITTLE INTENTION GOES A LONG WAY','Make a plan. Make it yours.','Regular income and commitments that carry your month forward.'],insights:['Insights','SEE THE BIGGER PICTURE','Clarity in every number.','Discover where your money goes and how your month is taking shape.'],qr:['QR Transfer','DIRECT DEVICE TRANSFER','QR Transfer','Send and receive records without a cloud account.'],files:['Excel files','YOUR DATA, YOUR CHOICE','Take your ledger with you.','Import, export and share your Excel files. No account required.'],stats:['Stats','YOUR RECORDED PATTERNS','Stats','Income and expense categories by period.'],settings:['Settings','PERSONAL BY DESIGN','A space that feels like you.','Your appearance, your workspace, your choices.']};
function displayName(value){const v=String(value||'').trim().replace(/\s+/g,' ');return v?v[0].toUpperCase()+v.slice(1).toLowerCase():''}
function normalizedPage(p){return ({overview:'home',transactions:'history',preferences:'settings',profile:'settings'})[p]|| (titles[p]?p:'home')}
let navigationReady=false,lastHomeBack=0,leavingApp=false;
function initializeNavigation(requested){if(navigationReady&&!leavingApp)return;navigationReady=true;leavingApp=false;lastHomeBack=0;window.history.replaceState({nidhiBase:true},'','#home');window.history.pushState({nidhiApp:true},'','#'+normalizedPage(requested))}
function go(p,options={}){p=normalizedPage(p);if(!isUnlocked())return;if(p==='history'&&!options.keepFilter){historyFilter=null;historyAt=page==='home'?new Date(selected+'-01T12:00').getTime():Date.now();if(page==='home')historyUnit='monthly'}page=p;lastHomeBack=0;if(navigationReady)window.history.replaceState({nidhiApp:true},'','#'+page);render();window.scrollTo({top:0,behavior:'smooth'})}
function backToHome(fromPop=false){if(!isUnlocked())return;if(page!=='home'){page='home';lastHomeBack=0;if(fromPop)window.history.pushState({nidhiApp:true},'','#home');else window.history.replaceState({nidhiApp:true},'','#home');render();scrollTo(0,0);return}const now=Date.now();if(now-lastHomeBack<=2200&&lastHomeBack){leavingApp=true;lock();window.history.back();return}lastHomeBack=now;toast('Press Back again to leave Nidhi.');window.history.pushState({nidhiApp:true},'','#home')}
window.addEventListener('popstate',()=>{if(!navigationReady||leavingApp)return;if(!isUnlocked()){if(page!=='home'){page='home';window.history.pushState({nidhiApp:true},'','#home');return}leavingApp=true;window.history.back();return}if($('#modal').open){$('#modal').close();window.history.pushState({nidhiApp:true},'','#'+page);return}backToHome(true)});
function openStatsCategory(filter){historyFilter=filter;query='';type=filter.type;account='ALL';go('history',{keepFilter:true})}

function empty(title='Start with a little clarity',text='Add your first transaction or import your existing Nidhi Android Excel file. Your real numbers will appear here.'){return `<div class="empty"><div class="empty-icon">◫</div><h3>${title}</h3><p>${text}</p><button class="primary" data-add>＋ Add transaction</button><button class="secondary" data-import>Import Excel ↗</button></div>`}
function table(items){return `<div class="transaction-list">${items.map(t=>recordRow({title:displayName(t.note||t.category),subtitle:date(t.dateTime)+' · '+t.account+' · '+t.category,amount:(t.type==='INCOME'?'+':'−')+money(t.amount),color:t.type==='INCOME'?'var(--green)':'var(--red)',attribute:'data-tx',id:t.id})).join('')}</div>`}

function cashChart(tx){const [y,m]=selected.split('-').map(Number),days=new Date(y,m,0).getDate(),values=Array.from({length:days},()=>[0,0]);tx.forEach(t=>values[new Date(t.dateTime).getDate()-1][t.type==='INCOME'?0:1]+=t.amount);const max=Math.max(100,...values.flat());const x=i=>38+i/(days-1)*555,yv=n=>177-n/max*145;const points=k=>values.map((v,i)=>`${x(i)},${yv(v[k])}`).join(' ');return `<svg class="chart" viewBox="0 0 610 205" role="img" aria-label="Daily income and expense chart">${[0,.5,1].map(v=>`<line class="chart-grid" x1="38" y1="${yv(max*v)}" x2="596" y2="${yv(max*v)}"/><text class="chart-axis" x="0" y="${yv(max*v)+3}">${money(max*v).replace(/\.\d+$/,'')}</text>`).join('')}<defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#387a5e" stop-opacity=".16"/><stop offset="1" stop-color="#387a5e" stop-opacity="0"/></linearGradient></defs><polygon points="38,177 ${points(1)} 593,177" fill="url(#area)"/><polyline fill="none" stroke="var(--green)" stroke-width="2.4" stroke-linejoin="round" points="${points(0)}"/><polyline fill="none" stroke="var(--red)" stroke-width="2.4" stroke-linejoin="round" points="${points(1)}"/>${[1,8,15,22,days].map(d=>`<text x="${x(d-1)}" y="201" class="chart-axis" text-anchor="middle">${d} ${new Date(y,m-1,1).toLocaleDateString('en',{month:'short'})}</text>`).join('')}</svg>`}
function categories(tx){const map=new Map();for(const t of tx.filter(t=>t.type==='EXPENSE'))map.set(t.category,(map.get(t.category)||0)+t.amount);return [...map].sort((a,b)=>b[1]-a[1])}
function donut(tx){const cats=categories(tx);if(!cats.length)return `<div class="empty"><h3>No expenses yet</h3><p>Your spending breakdown will appear after you record an expense.</p></div>`;const first=cats.slice(0,4);if(cats.length>4)first.push(['More categories',cats.slice(4).reduce((n,c)=>n+c[1],0)]);const total=first.reduce((n,c)=>n+c[1],0);let pos=0;const stops=first.map((c,i)=>{const start=pos;pos+=c[1]/total*100;return `${palette[i]} ${start}% ${pos}%`}).join(',');return `<div class="donut-wrap"><div class="donut" style="background:conic-gradient(${stops})"><div class="donut-center">${money(total)}<small>TOTAL SPENT</small></div></div><div class="category-legend">${first.map((c,i)=>`<div><i style="background:${palette[i]}"></i>${esc(c[0])}<b>${Math.round(c[1]/total*100)}%</b></div>`).join('')}</div></div>`}
function spendingGradient(ratio){const t=Math.max(0,Math.min(1,ratio)),green=[32,100,75],red=[153,76,62],base=green.map((n,i)=>Math.round(n+(red[i]-n)*t)),end=base.map((n,i)=>Math.round(n*.8+[15,30,24][i]*.2));return `linear-gradient(135deg,rgb(${base.join(',')}),rgb(${end.join(',')}))`}
function homeActions(){return `<div class="home-action-stack"><section class="card"><h2>Add transaction</h2><div class="home-action-grid"><button class="home-action-tile" data-add><span class="action-symbol">＋</span><b>Manual entry</b><small>Add income or expense</small><i>›</i></button><button class="home-action-tile" data-import><span class="action-symbol">▤</span><b>Import Excel</b><small>Bring existing records</small><i>›</i></button></div></section><section class="card"><h2>QR transfer</h2><div class="home-action-grid"><button class="home-action-tile" data-qr="send"><span class="action-symbol">▦</span><b>Send records</b><small>Share records via QR</small><i>›</i></button><button class="home-action-tile" data-qr="receive"><span class="action-symbol">⌗</span><b>Receive records</b><small>Scan records from Nidhi</small><i>›</i></button></div></section></div>`}
function home(){const c=calc(),ratio=c.limit?c.spentToday/c.limit:c.spentToday?1:0;return `<div class="grid overview-top"><section class="card hero" style="background:${spendingGradient(ratio)}"><span class="hero-label">${selected===monthOf(Date.now())?"Today's":"Daily"} spending allowance</span><div class="big"><span>₹</span>${money(Math.max(0,c.limit-c.spentToday)).replace('₹','')}</div><div class="hero-sub">${ratio>1?'Over your allowance by '+money(c.spentToday-c.limit):'left to spend'+(c.base?' · '+money(c.limit)+' daily allowance':' · add income or set a monthly plan')}</div><div class="hero-bottom"><div class="progress"><span style="width:${Math.min(100,ratio*100)}%"></span></div><div class="progress-caption"><span>${money(c.spentToday)} spent today</span><span>${Math.round(ratio*100)}% used</span></div></div></section><section class="card month-card"><div class="card-head"><h2>This month</h2><small>${new Date(selected+'-01T12:00').toLocaleDateString('en-IN',{month:'long',year:'numeric'})}</small></div><div class="metrics"><div class="metric"><span class="metric-label"><span class="metric-icon positive">↙</span> Income</span><div class="money positive">${money(c.income)}</div><small>Money coming in</small></div><div class="metric"><span class="metric-label"><span class="metric-icon negative">↗</span> Expenses</span><div class="money negative">${money(c.expense)}</div><small>Money going out</small></div></div><div class="balance"><span class="muted">Remaining balance</span><b class="${c.balance>=0?'positive':'negative'}">${money(c.balance)}</b></div></section></div>${c.tx.length?`<div class="grid overview-mid"><section class="card"><div class="card-head"><h2>Cash flow</h2><div class="legend"><span><i style="background:var(--green)"></i>Income</span><span><i style="background:var(--red)"></i>Expenses</span></div></div>${cashChart(c.tx)}</section><section class="card"><div class="card-head"><h2>Where it goes</h2><button class="text-btn" data-page="insights">Details ↗</button></div>${donut(c.tx)}</section></div>`:`<section class="card" style="margin-top:20px">${empty()}</section>`}<div class="grid overview-bottom"><section class="card"><div class="card-head"><h2>Recent transactions</h2><button class="text-btn" data-page="history">View all ↗</button></div>${c.tx.length?table([...c.tx].sort((a,b)=>b.dateTime-a.dateTime).slice(0,5)):'<p class="hint">Your most recent activity will live here.</p>'}</section><section class="card plan-promo"><h2>Monthly plan</h2><p>Your regular income and commitments.</p><div class="mini-stats"><div><b>${money(c.reserved)}</b><small>Reserved this month</small></div><div><b>${c.days-c.day+1}</b><small>Days remaining</small></div></div><button class="primary" data-page="plan">Open monthly plan ↗</button></section></div>${homeActions()}`}
function historyBounds(){const from=calendarStart(historyAt,historyUnit);return {from,to:calendarNext(from,historyUnit)}}
function getHistoryRows(){const bounds=historyBounds();return state.transactions.filter(t=>t.dateTime>=bounds.from&&t.dateTime<bounds.to)}
function historyControls(){const from=calendarStart(historyAt,historyUnit);return `${!historyFilter?`<div class="period-navigation"><button class="icon-btn" id="history-prev" aria-label="Previous period">‹</button><h2>${esc(calendarLabel(from,historyUnit))}</h2><button class="icon-btn" id="history-next" aria-label="Next period">›</button><select id="history-unit" aria-label="History period">${['weekly','monthly','yearly'].map(v=>`<option value="${v}" ${historyUnit===v?'selected':''}>${v[0].toUpperCase()+v.slice(1)}</option>`).join('')}</select></div>`:''}<div class="segmented history-type-tabs" role="tablist" aria-label="Transaction type">${[['ALL','All'],['INCOME','Income'],['EXPENSE','Expenses']].map(([v,label])=>`<button data-history-type="${v}" role="tab" aria-selected="${type===v}">${label}</button>`).join('')}</div>`}
function history(){let tx=(historyFilter?state.transactions.filter(t=>t.dateTime>=historyFilter.from&&t.dateTime<historyFilter.to&&norm(t.category)===norm(historyFilter.name)):getHistoryRows()).filter(t=>(type==='ALL'||t.type===type)&&(account==='ALL'||t.account===account)&&norm(`${t.note} ${t.category} ${t.account} ${t.description}`).includes(norm(query))).sort((a,b)=>b.dateTime-a.dateTime);return `<section class="card">${historyControls()}${historyFilter?`<div class="notice category-drilldown"><span>${esc(historyFilter.name)} · ${esc(historyFilter.label)}</span><button class="text-btn" id="clear-history-category">Clear ✕</button></div>`:''}<div class="toolbar"><input id="search" placeholder="Search transactions, categories or notes" value="${esc(query)}" aria-label="Search transactions"><select id="account" aria-label="Account">${['ALL',...new Set(state.transactions.map(t=>t.account))].map(v=>`<option value="${esc(v)}" ${v===account?'selected':''}>${esc(v)}</option>`).join('')}</select><button class="icon-btn" id="history-files" aria-label="Import or export Excel">⇅</button></div><div class="card-head"><small>${tx.length} transactions · ${money(sum(tx.filter(t=>t.type==='EXPENSE')))} expenses</small></div>${tx.length?table(tx):empty('No transactions to show','Try another month or filter, add a transaction, or import your Android Excel file.')}</section>`}
function planList(kind){const arr=state.budget[kind].filter(x=>x.month===selected),income=kind==='incomeSources';return `<section class="card"><div class="card-head"><h2>${income?'Regular income':'Monthly commitments'}</h2><button class="text-btn" data-new-plan="${kind}">＋ Add new</button></div><p class="hint">${income?'Salary, rent, business or another source. Check only when received.':'Rent, SIP, insurance or savings. Check only when paid.'}</p>${arr.length?arr.map(x=>{const checked=state.transactions.some(t=>key(t)===x.paymentKey);return `<div class="plan-row"><input type="checkbox" data-plan-check="${esc(x.id)}" data-kind="${kind}" ${checked?'checked':''} aria-label="${income?'Mark received':'Mark paid'} ${esc(x.name)}"><span class="grow">${esc(x.name)}<small>${checked?income?'Received':'Paid':'Pending'} · repeats next month</small></span><b>${money(x.amount)}</b><button data-edit-plan="${esc(x.id)}" data-kind="${kind}" aria-label="Edit ${esc(x.name)}">✎</button></div>`}).join(''):`<div class="empty"><h3>${income?'Plan your income':'Make room for commitments'}</h3><p>${income?'Add salary, rental income, business or your own source.':'Add recurring essentials like rent, EMI, SIP or insurance.'}</p><button class="secondary" data-new-plan="${kind}">＋ Add new</button></div>`}</section>`}
function plan(){const c=calc();return `<div class="summary-strip"><div class="card"><small>Planned monthly income</small><b class="positive">${money(c.base)}</b><button class="text-btn" id="set-budget">Set budget ↗</button></div><div class="card"><small>Reserved for commitments</small><b>${money(c.reserved)}</b></div><div class="card"><small>Daily allowance</small><b>${money(c.limit)}</b></div></div><div class="grid two-col">${planList('incomeSources')}${planList('commitments')}</div><div class="notice">Checking an item records a transaction immediately. Unchecking removes its linked transaction after confirmation. Future months carry your configured items forward as pending. Existing imported plan amounts and payment links are preserved.</div><button class="secondary" id="carry-plan">Carry previous month’s plan forward ↗</button>`}
function insights(){return analysisPage(state)}
function settings(){return `<div class="grid two-col"><section class="card"><div class="card-head"><h2>App updates</h2><button class="secondary" id="check-app-update">Check for updates</button></div><p id="update-check-status" class="hint" role="status">UI build 22 · Updates keep your saved records and PIN. Finish entering changes before updating.</p></section><section class="card"><h2>Account</h2><div class="settings-row"><div><b>Your name</b><small>Stored on this device.</small></div><button class="secondary" id="set-name">${esc(prefs.name||'Add name')} ✎</button></div></section><section class="card"><h2>Monthly plan</h2><div class="settings-row"><div><b>Regular income & commitments</b><small>Configure the amounts carried into each month.</small></div><button class="secondary" data-page="plan">Open ›</button></div></section><section class="card"><h2>Appearance</h2><div class="settings-row"><div><b>Theme</b><small>Find your comfortable view.</small></div><select id="theme-select" aria-label="Theme">${['light','dark','system'].map(v=>`<option value="${v}" ${prefs.theme===v?'selected':''}>${v[0].toUpperCase()+v.slice(1)}</option>`).join('')}</select></div><div class="settings-row"><div><b>Accent colour</b><small>Make the details feel like you.</small></div><div class="swatches">${['#28634e','#375f8e','#65548e','#925141','#8b6235','#476c6c'].map(v=>`<button data-accent="${v}" class="${prefs.accent===v?'chosen':''}" style="background:${v}" aria-label="Use ${v}"></button>`).join('')}<input type="color" id="custom-accent" value="${prefs.accent}" aria-label="Custom accent" style="width:27px;height:27px;border:0;padding:0"></div></div><div style="padding-top:20px"><b>Workspace background</b><p class="hint">Subtle colour, a little atmosphere.</p><div class="wallpapers">${[['plain','Plain','var(--bg)'],['mist','Meadow','linear-gradient(140deg,#bdd7c4,#eff3e6)'],['dune','Dune','linear-gradient(140deg,#e5c8a3,#f7eee1)'],['aurora','Aurora','linear-gradient(140deg,#c4b9e0,#c4e5db)']].map(([id,name,bg])=>`<button data-wallpaper="${id}" class="${prefs.wallpaper===id?'chosen':''}" style="background:${bg};color:#24382c">${name}</button>`).join('')}</div></div></section><section class="card"><h2>App access & transfer</h2><div class="settings-row"><div><b>Six-digit PIN lock</b><small>Required whenever the app opens or returns to the screen.</small></div><button class="secondary" id="lock-now">Lock now</button></div><div class="settings-row"><div><b>QR transfer</b><small>Scan each QR to import its records; duplicates are skipped.</small></div><button class="secondary" data-page="qr">Open ↗</button></div></section><section class="card"><h2>Categories & accounts</h2><div class="settings-row"><div><b>Categories</b><small>Organise your income and expenses.</small></div><button class="secondary" id="manage-categories">Manage ↗</button></div><div class="settings-row"><div><b>Accounts</b><small>Cash, bank accounts, cards and more.</small></div><button class="secondary" id="manage-accounts">Manage ↗</button></div></section>${reminderSettings()}<section class="card"><h2>Excel & local data</h2><div class="settings-row"><div><b>Excel files</b><small>Import, create, download or share records.</small></div><button class="secondary" data-page="files">Open ›</button></div><div class="settings-row"><div><b>Automatic Excel creation</b><small>Create a file when Nidhi is open and the interval is due.</small></div><span class="tag">Daily · always on</span></div><p class="hint">Mandatory daily file preparation: once each calendar day. If the app was closed, creation runs next time you open it. A file is prepared locally; choose Download or Share to save it outside this browser.</p><div class="settings-row"><div><b>Import Android Excel</b><small>Preview and skip matching transactions.</small></div><button class="secondary" data-import>Import ↑</button></div><div class="settings-row"><div><b>Export & share Excel</b><small>All months and monthly plans, with duplicate rows removed.</small></div><button class="secondary" data-export>Create XLSX</button></div><div class="settings-row"><div><b>Local storage</b><small>${state.transactions.length} records on this browser.</small></div><button class="text-btn" id="persist-storage">Keep offline</button></div><div class="settings-row"><div><b class="danger">Clear this device</b><small>Export your ledger first. Downloaded files are unchanged.</small></div><button class="text-btn danger" id="clear-data">Clear</button></div><p class="hint">No account or cloud integration. Excel files are not encrypted.</p></section></div><section class="card" style="margin-top:20px"><div class="card-head"><div><span class="eyebrow">DESIGNED & DEVELOPED BY</span><h2 style="margin-top:10px">Pruthvi Raj CP</h2></div><a class="secondary" href="https://ram-clef.github.io/portfolio/" target="_blank" rel="noopener">Explore portfolio ↗</a></div><div class="detail-actions"><a class="text-btn" href="https://www.linkedin.com/in/pruthviraj-cp/" target="_blank" rel="noopener">LinkedIn ↗</a><a class="text-btn" href="mailto:clef2k22@gmail.com">Email ↗</a><a class="text-btn" href="https://github.com/pruthviraj1441" target="_blank" rel="noopener">GitHub ↗</a></div></section>`}
function render(){if(!state||!isUnlocked())return;stopQr();const t=titles[page];document.querySelector('.app-wordmark').innerHTML='<img src="./icon.svg" alt="">'+(page==='home'?'nidhi.':({history:'History',insights:'Analyze'})[page]||t[0]);$('#page-label').textContent=t[0];$('#eyebrow').textContent=t[1];$('#page-title').textContent=({home:'Home',stats:'Stats',history:'History',plan:'Monthly plan',insights:'Analyze',qr:'QR Transfer',files:'Excel files',settings:'Settings',notifications:'Notifications'})[page];$('#page-subtitle').textContent=({home:prefs.name?'Welcome, '+prefs.name:'A clear view of your day',stats:'Your income and expense categories',history:'Your income and expenses',plan:'Plan ahead, one month at a time',insights:'Understand your spending',qr:'Direct transfer between devices',files:'Import, export and share',settings:'Personalise your Nidhi',notifications:'Your reminders and summaries'})[page];if($('#month-display'))$('#month-display').textContent=new Date(selected+'-01T12:00').toLocaleDateString('en-IN',{month:'long',year:'numeric'})+' ▾';$('#month').parentElement.hidden=(['files','settings','insights','qr','stats','history','notifications'].includes(page)||page==='history'&&!!historyFilter);document.body.dataset.page=page;document.querySelector('.app-back').hidden=page==='home';document.querySelectorAll('.sidebar nav button').forEach(b=>{const active=page==='insights'?'stats':['plan','files','qr','notifications'].includes(page)?'settings':page;b.classList.toggle('active',b.dataset.page===active);if(b.dataset.page===active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});$('#content').innerHTML=({home,stats:()=>statsPage(state),history,plan,insights,files:filesPage,qr:qrPage,notifications:notificationPage,settings})[page]();bindPage()}
function bindPage(){document.querySelectorAll('[data-history-type]').forEach(b=>b.onclick=()=>{type=b.dataset.historyType;render()});if($('#history-unit')){$('#history-unit').onchange=e=>{historyUnit=e.target.value;historyAt=Date.now();render()};$('#history-prev').onclick=()=>{historyAt=calendarNext(calendarStart(historyAt,historyUnit),historyUnit,-1);render()};$('#history-next').onclick=()=>{historyAt=calendarNext(calendarStart(historyAt,historyUnit),historyUnit,1);render()}}bindStats(render,openStatsCategory);bindQr({getState:()=>state,receipts:async()=>await secureRead('qr-receipts')||{},commitBatch:commitQrBatch});if(qrIntent&&page==='qr'){const intent=qrIntent;qrIntent=null;queueMicrotask(()=>{if(page==='qr'&&isUnlocked())$('#qr-'+intent)?.click()})}bindReminders();bindAnalysis(render);if($('#export-frequency'))$('#export-frequency').onchange=e=>{exportPrefs.frequency=e.target.value;localStorage.setItem('nidhi-export-prefs',JSON.stringify(exportPrefs));render();checkScheduledExport()};if($('#search'))$('#search').oninput=e=>{const start=e.target.selectionStart;query=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(start,start)};if($('#type'))$('#type').onchange=e=>{type=e.target.value;render()};if($('#account'))$('#account').onchange=e=>{account=e.target.value;render()};if($('#theme-select'))$('#theme-select').onchange=e=>{prefs.theme=e.target.value;appearance();render()};if($('#custom-accent'))$('#custom-accent').oninput=e=>{prefs.accent=e.target.value;appearance()};document.querySelectorAll('[data-plan-check]').forEach(el=>el.onchange=()=>togglePlan(el));}
function catalogItems(kind,type='EXPENSE'){
 const categoryDefaults=type==='INCOME'?['Salary','Business','Rental income','Other income']:['Food & drinks','Shopping','Travel','Bills','Rent','Commitments','Other'];
 const defaults=(kind==='accounts'?['Cash','Bank account','Credit card','Default']:categoryDefaults).map(name=>({name,...(kind==='categories'?{type}: {})}));
 const stored=(state.budget.webCatalogs?.[kind]||[]).filter(x=>kind==='accounts'||x.type===type);
 const recorded=state.transactions.filter(t=>kind==='accounts'||t.type===type).map(t=>({name:kind==='accounts'?t.account:t.category,type:t.type,emoji:t.emoji||''}));
 const result=new Map();for(const x of [...defaults,...recorded,...stored])if(x.name?.trim())result.set(norm(x.name).replace(/\s+/g,' '),x);
 const hidden=state.budget.webHidden?.[kind]||[];return [...result.values()].filter(x=>!hidden.some(h=>norm(h.name)===norm(x.name)&&(kind==='accounts'||h.type===type))).sort((a,b)=>a.name.localeCompare(b.name));
}
function catalogOptions(kind,type,selected=''){
 const items=catalogItems(kind,type);
 return `<option value="" disabled ${selected?'':'selected'}>Choose ${kind==='categories'?'category':'account'}</option>${items.map(x=>`<option value="${esc(x.name)}" ${norm(x.name)===norm(selected)?'selected':''}>${esc(x.name)}</option>`).join('')}<option value="__create__">＋ Create new ${kind==='categories'?'category':'account'}…</option>`;
}
function manageCatalog(kind){
 const cat=kind==='categories',types=cat?['EXPENSE','INCOME']:['ALL'];
 modal(`<h2>${cat?'Categories':'Accounts'}</h2><p>Choose these from the dropdown when recording a transaction.</p>${types.map(type=>`<section class="catalog-group">${cat?`<h3>${type==='INCOME'?'Income':'Expenses'}</h3>`:''}${catalogItems(kind,type).map(x=>`<div class="catalog-row"><span class="catalog-symbol">${cat?'▦':'▣'}</span><span class="grow">${esc(x.name)}</span><button type="button" class="text-btn" data-manage-name="${esc(x.name)}" data-manage-type="${type}">Move / delete</button></div>`).join('')}</section>`).join('')}`,`<button class="secondary" type="button" data-close>Close</button><button class="primary" type="button" id="new-catalog-item">＋ Create new</button>`);
 document.querySelectorAll('[data-manage-name]').forEach(b=>b.onclick=()=>manageCatalogEntry(kind,b.dataset.manageType,b.dataset.manageName));$('#new-catalog-item').onclick=()=>{close();catalogForm(kind,'EXPENSE',null,()=>manageCatalog(kind))};
}
function manageCatalogEntry(kind,type,name){
 const cat=kind==='categories',targets=catalogItems(kind,type).filter(x=>norm(x.name)!==norm(name));
 modal(`<h2>Move or delete ${cat?'category':'account'}</h2><p>${esc(name)}. Existing records are kept and moved to the destination. The old option is removed.</p><div class="fields"><label>Move existing records to<select name="target" required><option value="" disabled selected>Choose destination</option>${targets.map(x=>`<option>${esc(x.name)}</option>`).join('')}</select></label></div>`,`<button class="secondary" type="button" data-close>Close</button><button class="primary" type="submit">Move &amp; remove</button>`,async fd=>{
 const target=fd.get('target');if(!target)throw Error('Choose a destination.');const n=structuredClone(state),aliases=new Map();
 for(const t of n.transactions)if((!cat||t.type===type)&&norm(cat?t.category:t.account)===norm(name)){const before=key(t);if(cat){t.category=target;t.emoji=targets.find(x=>x.name===target)?.emoji||''}else t.account=target;aliases.set(before,key(t))}
 for(const group of ['incomeSources','commitments'])for(const item of n.budget[group])if(aliases.has(item.paymentKey))item.paymentKey=aliases.get(item.paymentKey);
 n.budget.webHidden??={};n.budget.webHidden[kind]??=[];n.budget.webHidden[kind].push({name,type});n.budget.webCatalogs??={};n.budget.webCatalogs[kind]=(n.budget.webCatalogs[kind]||[]).filter(x=>norm(x.name)!==norm(name)||(cat&&x.type!==type));await commit(n);close();manageCatalog(kind)
 });
}
function catalogForm(kind,type,id,done){
 const cat=kind==='categories',fromTransaction=!!document.querySelector('#tx-category');
 modal(`<h2>Create ${cat?'category':'account'}</h2><p>${cat?'Give your transactions a place.':'Add a cash wallet, bank account, card or another account.'}</p><div class="fields">${cat?`<label>For<select name="type" ${fromTransaction?'disabled':''}><option value="EXPENSE" ${type==='EXPENSE'?'selected':''}>Expenses</option><option value="INCOME" ${type==='INCOME'?'selected':''}>Income</option></select></label>`:''}<label>${cat?'Category':'Account'} name<input name="name" required maxlength="80" autocomplete="off" placeholder="${cat?'e.g. Healthcare':'e.g. Personal savings account'}"></label></div>`,action('Create'),async fd=>{
  const name=fd.get('name').trim().replace(/\s+/g,' '),forType=cat?(fd.get('type')||type):'ALL';
  if(!name||name==='__create__')throw Error('Enter a valid name.');
  if(catalogItems(kind,forType).some(x=>norm(x.name).replace(/\s+/g,' ')===norm(name)))throw Error('This '+(cat?'category':'account')+' already exists. Choose it from the dropdown.');
  const next=structuredClone(state);next.budget.webCatalogs??={categories:[],accounts:[]};next.budget.webCatalogs[kind]??=[];next.budget.webHidden??={};next.budget.webHidden[kind]=(next.budget.webHidden[kind]||[]).filter(x=>norm(x.name)!==norm(name)||(cat&&x.type!==forType));next.budget.webCatalogs[kind].push({name,...(cat?{type:forType}: {})});
  await commit(next);completed=true;$('#modal').removeEventListener('close',cancelled);close();done?.(name);toast((cat?'Category':'Account')+' created');
 });
 let completed=false;
 function cancelled(){if($('#modal').open)return;$('#modal').removeEventListener('close',cancelled);if(!completed&&isUnlocked())done?.('')}
 $('#modal').addEventListener('close',cancelled);
}

function txForm(t,draft={}){const v={...t,...draft};const local=new Date(v.dateTime||Date.now());local.setMinutes(local.getMinutes()-local.getTimezoneOffset());modal(`<h2>${t?'Edit transaction':'Add transaction'}</h2><p>Record what came in or went out.</p><div class="fields two-col"><label>Type<select name="type">${['EXPENSE','INCOME'].map(v=>`<option ${(draft.type||t?.type||'EXPENSE')===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Amount (₹)<input name="amount" type="number" step=".01" min=".01" max="9999999999" required value="${v.amount?v.amount/100:''}" placeholder="0.00"></label><label>Category<select name="category" id="tx-category" required>${catalogOptions('categories',v.type||'EXPENSE',v.category)}</select></label><label>Account<select name="account" id="tx-account" required>${catalogOptions('accounts',v.type||'EXPENSE',v.account||'Cash')}</select></label><label class="full">Note<select id="note-choice" aria-label="Choose an existing note"><option value="">Write a note…</option>${[...new Map(state.transactions.filter(x=>x.note?.trim()).map(x=>[norm(x.note),displayName(x.note)])).values()].sort().map(n=>`<option>${esc(n)}</option>`).join('')}</select><input name="note" maxlength="300" value="${esc(v.note||'')}" placeholder="What was it for?"></label><label class="full">Date & time<input name="dateTime" type="datetime-local" required value="${local.toISOString().slice(0,16)}"></label></div>`,action(t?'Save changes':'Save transaction'),async fd=>{const amount=Math.round(Number(fd.get('amount'))*100),dateTime=new Date(fd.get('dateTime')).getTime();if(!Number.isSafeInteger(amount)||amount<=0||!Number.isFinite(dateTime))throw Error('Enter a valid amount and date.');const record={...t,id:t?.id||crypto.randomUUID(),type:fd.get('type'),amount,dateTime,category:fd.get('category').trim(),account:fd.get('account').trim(),note:displayName(fd.get('note')),emoji:catalogItems('categories',fd.get('type')).find(x=>norm(x.name)===norm(fd.get('category')))?.emoji||t?.emoji||'',description:t?.description||'',reference:t?.reference||'',counterparty:t?.counterparty||''};if(!record.category||!record.account)throw Error('Category and account are required.');const existing=state.transactions.find(x=>x.id!==t?.id&&(key(x)===key(record)||(record.reference&&norm(x.reference)===norm(record.reference))));if(existing)throw Error('This transaction already exists.');const n=structuredClone(state);const oldKey=t&&key(t);n.transactions=t?n.transactions.map(x=>x.id===t.id?record:x):[...n.transactions,record];if(oldKey)for(const kind of ['incomeSources','commitments'])n.budget[kind].forEach(x=>{if(x.paymentKey===oldKey)x.paymentKey=key(record)});await commit(n);close();toast('Transaction saved')});
 const takeDraft=()=>{const fd=new FormData($('#modal-form'));return {type:fd.get('type'),amount:Math.round(Number(fd.get('amount'))*100),dateTime:new Date(fd.get('dateTime')).getTime()||v.dateTime||Date.now(),category:fd.get('category')==='__create__'?'':fd.get('category'),account:fd.get('account')==='__create__'?'':fd.get('account'),note:fd.get('note')}};
 $('#modal-form select[name=type]').onchange=e=>{$('#tx-category').innerHTML=catalogOptions('categories',e.target.value,'')};
 for(const [selector,kind] of [['#tx-category','categories'],['#tx-account','accounts']])$(selector).onchange=e=>{if(e.target.value!=='__create__')return;const data=takeDraft();close();catalogForm(kind,data.type,null,name=>txForm(t,{...data,[kind==='categories'?'category':'account']:name||data[kind==='categories'?'category':'account']}))};
}
function detail(id){const t=state.transactions.find(t=>t.id===id);if(!t)return;modal(`<h2>${esc(displayName(t.note||t.category))}</h2><h1 class="${t.type==='INCOME'?'positive':'negative'}">${t.type==='INCOME'?'+':'−'}${money(t.amount)}</h1><p>${esc(t.category)} · ${esc(t.account)}<br>${esc(new Date(t.dateTime).toLocaleString())}</p>${t.description?`<p>${esc(t.description)}</p>`:''}${t.reference?`<p>Reference: ${esc(t.reference)}</p>`:''}`,`<button class="secondary" type="button" id="close-tx">Close</button><button class="secondary danger" type="button" id="delete-tx">Delete</button><button class="primary" type="button" id="edit-tx">Edit transaction</button>`);$('#close-tx').onclick=close;$('#edit-tx').onclick=()=>{close();txForm(t)};$('#delete-tx').onclick=()=>{close();confirmDialog('Delete this transaction?','The record will be removed from this browser. Existing exported files are unchanged.',async()=>{const n=structuredClone(state);n.transactions=n.transactions.filter(x=>x.id!==id);for(const kind of ['incomeSources','commitments'])n.budget[kind].forEach(x=>{if(x.paymentKey===key(t)){x.paymentKey='';x.paidAt=0;x.creditedAt=0}});await commit(n);toast('Transaction deleted')},'Delete transaction')}}
function confirmDialog(title,text,fn,label='Confirm'){modal(`<h2>${title}</h2><p>${text}</p>`,action(label),async()=>{await fn();close()})}
function planForm(kind,id){const item=state.budget[kind].find(x=>x.id===id),income=kind==='incomeSources';modal(`<h2>${item?'Edit': 'Add'} ${income?'income source':'commitment'}</h2><p>Repeats in future months until you remove it.</p><div class="fields"><label>Name<select name="name" id="plan-name-choice" required><option value="" disabled ${item?'':'selected'}>Select ${income?'income source':'commitment'}</option>${[...new Set([...(item?[item.name]:[]),...(income?['Salary','Rental income','Business','Trading','Other income']:['Rent','EMI','SIP','Insurance','Savings','Utilities'])])].map(v=>`<option value="${esc(v)}" ${item?.name===v?'selected':''}>${esc(v)}</option>`).join('')}<option value="__new__">＋ Add new…</option></select></label><label id="plan-custom-field" hidden>New name<input name="customName" maxlength="80" autocomplete="off" placeholder="Enter a name"></label><label>Amount (₹)<input type="number" name="amount" required min=".01" max="9999999999" step=".01" value="${item?item.amount/100:''}" placeholder="0.00"></label></div>`,`${item?'<button class="text-btn danger" type="button" id="delete-plan">Remove</button>':''}${action()}`,async fd=>{const name=displayName(fd.get('name')==='__new__'?fd.get('customName'):fd.get('name')),amount=Math.round(Number(fd.get('amount'))*100);if(!name||!Number.isSafeInteger(amount)||amount<=0)throw Error('Enter a name and positive amount.');if(state.budget[kind].some(x=>x.id!==id&&x.month===selected&&norm(x.name)===norm(name)))throw Error('An item with this name already exists.');const n=structuredClone(state);const row={...item,id:id||crypto.randomUUID(),month:selected,name,amount,enabled:true,paymentKey:item?.paymentKey||'',paidAt:item?.paidAt||0,creditedAt:item?.creditedAt||0};n.budget[kind]=id?n.budget[kind].map(x=>x.id===id?row:x):[...n.budget[kind],row];const linked=n.transactions.find(t=>key(t)===row.paymentKey);if(linked){linked.amount=amount;row.paymentKey=key(linked);n.budget[kind]=n.budget[kind].map(x=>x.id===row.id?row:x)}await commit(n);close();toast('Monthly plan saved')});$('#plan-name-choice').onchange=()=>{$('#plan-custom-field').hidden=$('#plan-name-choice').value!=='__new__';$('#plan-custom-field input').required=$('#plan-name-choice').value==='__new__'};if(item)$('#delete-plan').onclick=()=>{close();confirmDialog('Remove this recurring item?','Existing recorded payments remain in your transaction history.',async()=>{const n=structuredClone(state);n.budget[kind]=n.budget[kind].filter(x=>x.id!==id);await commit(n)},'Remove item')}}
async function togglePlan(el){const kind=el.dataset.kind,item=state.budget[kind].find(x=>x.id===el.dataset.planCheck),income=kind==='incomeSources';el.checked=!el.checked;const existing=state.transactions.find(t=>key(t)===item.paymentKey);confirmDialog(existing?'Remove linked transaction?':income?'Record this income?':'Record this payment?',existing?'Unchecking removes the transaction linked to this item.':`${esc(item.name)} · ${money(item.amount)} will be recorded for ${esc(selected)}. Matching records will be linked instead of duplicated.`,async()=>{const n=structuredClone(state),row=n.budget[kind].find(x=>x.id===item.id);if(existing){n.transactions=n.transactions.filter(t=>t.id!==existing.id);row.paymentKey='';row.paidAt=0;row.creditedAt=0}else{const matches=n.transactions.filter(t=>monthOf(t.dateTime)===selected&&t.type===(income?'INCOME':'EXPENSE')&&t.amount===item.amount&&(norm(t.note)===norm(item.name)||norm(t.category)===norm(item.name)));if(matches.length>1)throw Error('Multiple matching transactions found. Resolve the duplicate records first.');const [y,m]=selected.split('-').map(Number);const dateTime=selected===monthOf(Date.now())?Date.now():new Date(y,m-1,1,12).getTime();const t=matches[0]||{id:crypto.randomUUID(),type:income?'INCOME':'EXPENSE',amount:item.amount,dateTime,category:income?item.name:n.budget.commitmentCategory?.name||'Commitments',emoji:income?'↙':n.budget.commitmentCategory?.emoji||'🔁',account:'Default',note:item.name,description:'Monthly plan',reference:income?'':`commitment:${item.id}:${selected}`,counterparty:''};if(!matches.length)n.transactions.push(t);row.paymentKey=key(t);row[income?'creditedAt':'paidAt']=t.dateTime}await commit(n);toast('Monthly plan updated')},existing?'Remove transaction':income?'Mark received':'Mark paid')}
async function carry(silent=false){const [y,m]=selected.split('-').map(Number),previous=monthOf(new Date(y,m-2,1).getTime());const n=structuredClone(state);let count=0;for(const kind of ['incomeSources','commitments'])for(const x of n.budget[kind].filter(x=>x.month===previous&&x.enabled)){if(n.budget[kind].some(v=>v.month===selected&&norm(v.name)===norm(x.name)))continue;n.budget[kind].push({...x,id:crypto.randomUUID(),month:selected,paymentKey:'',paidAt:0,creditedAt:0});count++}const p=n.budget.plans.find(p=>p.month===previous);if(p&&!n.budget.plans.some(p=>p.month===selected))n.budget.plans.push({...p,month:selected});if(count||p)await commit(n);if(!silent)toast(count?`${count} recurring items carried forward`:'No new items to carry from the previous month')}
async function previewImport(bytes,name){const imported=await readExcel(bytes),result=merge(state,imported);modal(`<h2>Import Excel</h2><p>${esc(name)}</p><div class="summary-strip"><div class="card"><small>New entries</small><b>${result.added}</b></div><div class="card"><small>Duplicates</small><b>${result.duplicates}</b></div><div class="card"><small>Invalid rows</small><b>${imported.skipped}</b></div></div>${result.conflicts.length?`<div class="notice">${result.conflicts.length} matching records have changed values. Keep existing versions, or choose to update them below.</div><label class="catalog-row"><input type="checkbox" name="updateExisting"> Update matching records using this file</label>${result.conflicts.slice(0,8).map(c=>`<p class="hint">${esc(c.before.note||c.before.category)}: ${money(c.before.amount)} → ${money(c.after.amount)} · ${esc(c.after.note||c.after.category)}</p>`).join('')}`:''}<div class="notice">Existing data stays. Matching transaction references or date, amount, category, account, type and note are skipped. Monthly plan metadata is merged without replacing existing configurations.</div>`,action('Merge into Nidhi'),async fd=>{const fresh=merge(state,imported,{updateExisting:fd.has('updateExisting')});await commit(fresh.next);close();toast(`${fresh.added} added · ${fresh.updated} updated · ${fresh.duplicates} duplicates skipped`)})}
async function task(fn,message){if(busy)return;busy=true;$('#content').classList.add('busy');$('#storage-state').textContent=message||'Working…';try{await fn()}catch(e){toast(e.message)}finally{busy=false;$('#content').classList.remove('busy');$('#storage-state').textContent='Saved on this device'}}
document.addEventListener('click',async e=>{const b=e.target.closest('button,a,[data-tx]');if(!b)return;if(b.dataset.page){e.preventDefault();go(b.dataset.page)}else if(b.dataset.qr){qrIntent=b.dataset.qr;go('qr')}else if(b.hasAttribute('data-add'))txForm();else if(b.hasAttribute('data-import')){close();openFilePicker()}else if(b.hasAttribute('data-export')){close();task(exportExcel,'Preparing Excel…')}else if(b.dataset.tx)detail(b.dataset.tx);else if(b.dataset.newPlan)planForm(b.dataset.newPlan);else if(b.dataset.editPlan)planForm(b.dataset.kind,b.dataset.editPlan);else if(b.hasAttribute('data-close'))close();else if(b.dataset.accent){prefs.accent=b.dataset.accent;appearance();render()}else if(b.dataset.wallpaper){prefs.wallpaper=b.dataset.wallpaper;appearance();render()}else switch(b.id){case'history-files':modal('<h2>Excel files</h2><p>Import records or export a copy.</p>','<button class="secondary" type="button" data-close>Close</button><button class="secondary" type="button" data-import>Import</button><button class="primary" type="button" data-export>Export</button>');break;case'carry-plan':task(()=>carry(),'Updating monthly plan…');break;case'set-budget':{const p=state.budget.plans.find(p=>p.month===selected);modal('<h2>Monthly income budget</h2><p>Optional planned income for your daily allowance. Recorded income remains unchanged. Leave blank to use actual recorded income.</p><div class="fields"><label>Planned income (₹)<input type="number" min="0" max="9999999999" step=".01" name="income" value="'+(p?.income!=null?p.income/100:'')+'"></label></div>',action(),async fd=>{const v=fd.get('income'),income=v===''?null:Math.round(Number(v)*100);if(income!==null&&(!Number.isSafeInteger(income)||income<0))throw Error('Enter a valid amount.');const n=structuredClone(state);n.budget.plans=n.budget.plans.filter(p=>p.month!==selected);n.budget.plans.push({month:selected,income});await commit(n);close()});break}case'set-name':nameForm();break;case'clear-history-category':historyFilter=null;type='ALL';query='';render();break;case'lock-now':lock();break;case'manage-categories':manageCatalog('categories');break;case'manage-accounts':manageCatalog('accounts');break;case'prepare-export':task(exportExcel,'Creating Excel…');break;case'view-generated':if(generatedFile)openExport(generatedFile);break;case'persist-storage':task(async()=>{const yes=await navigator.storage?.persist?.();toast(yes?'Persistent storage enabled':'Your browser manages offline storage. Keep regular Excel exports.')});break;case'clear-data':confirmDialog('Clear the ledger on this device?','Download an Excel file first if needed. All local transactions and monthly plans will be removed. Exported files and Android records are untouched.',async()=>{await commit({transactions:[],budget:{version:1,plans:[],incomeSources:[],commitments:[]},updated:Date.now()});await clearGeneratedExport();await secureDelete('qr-receipts');clearReminderMessages();generatedFile=null;showExportBanner();toast('Local ledger cleared')},'Clear local data');break;case'privacy':modal('<h2>Your web privacy</h2><p>Your ledger, name and preferences are stored on this browser. No Google account or cloud API is connected. The local ledger and prepared Excel file are encrypted using a PIN-derived key. Six-digit PINs have limited entropy; keep your device and downloaded copies private. Imports are processed locally. Nothing is sent to a developer ledger server.</p><p>Excel files are not encrypted. Downloading saves a file through your browser. Sharing opens the device share sheet only when you choose Share; the destination app handles the file under its own policy. Name and ledger data are removed if browser site storage is cleared. QR transfer contains unencrypted transaction batches, compatible with updated Android Nidhi. Each scanned code is imported immediately with duplicate checks and completion receipts. Camera access is optional and only used when starting QR transfer. No images are uploaded.</p><p>Scheduled exports create one latest XLSX file locally when the app is open and due. They do not run reliably while the app is closed, and do not automatically send files to any third party. Download or share the generated file to keep a copy outside browser storage.</p><p>The web app cannot read SMS or other apps’ notifications. GitHub Pages receives normal network request information when serving app files; no ledger is included in those requests.</p><p>Optional reminders and morning/evening summaries are calculated locally while the app runs or when reopened. With your permission, financial amounts may appear in device notifications. No push subscription or notification backend is used.</p><p>Contact: <a href="mailto:clef2k22@gmail.com">clef2k22@gmail.com</a> · 3 November 2026</p>','<button type="button" class="primary" data-close>Understood</button>');break}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-tx]')){e.preventDefault();detail(e.target.dataset.tx)}});
$('#add').onclick=()=>txForm();$('#month').onchange=async e=>{if(!e.target.value)return;selected=e.target.value;render();await task(()=>carry(true))};$('#theme-toggle').onclick=()=>{prefs.theme=document.body.classList.contains('dark')?'light':'dark';appearance();render()};
function openFilePicker(){withSystemPrompt(()=>new Promise(resolve=>{const input=$('#file');const done=()=>{input.removeEventListener('change',done);input.removeEventListener('cancel',done);resolve()};input.addEventListener('change',done);input.addEventListener('cancel',done);input.click()})).catch(()=>{})}
async function importChosenFile(file){await task(async()=>{if(file.size>25*1024*1024)throw Error('Choose a workbook smaller than 25 MB.');await previewImport(await file.arrayBuffer(),file.name)},'Reading Excel…')}
$('#file').onchange=e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(!isUnlocked()){pendingImportFile=file;return}importChosenFile(file)};
const online=()=>$('#online-state').textContent=navigator.onLine?'● Offline ready':'● Working offline';window.addEventListener('online',online);window.addEventListener('offline',online);online();window.addEventListener('hashchange',()=>{if(!navigationReady||leavingApp||!isUnlocked())return;const next=normalizedPage(location.hash.slice(1));if(next!==page)go(next)});
const exportPrefs={...JSON.parse(localStorage.getItem('nidhi-export-prefs')||'{}'),frequency:'daily'};localStorage.setItem('nidhi-export-prefs',JSON.stringify(exportPrefs));
let generatedFile=null,exportRunning=false;
function periodId(frequency,now=new Date()){
  const localDay=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
  if(frequency==='monthly')return localDay(now).slice(0,7);
  if(frequency==='weekly'){const monday=new Date(now.getFullYear(),now.getMonth(),now.getDate());monday.setDate(monday.getDate()-((monday.getDay()+6)%7));return localDay(monday)}
  return localDay(now);
}
function nameForm(first=false){
  modal(`<h2>${first?'Welcome to Nidhi':'What should we call you?'}</h2><p>Your name is saved only in this browser. No account is needed.</p><div class="fields"><label>Your name<input name="name" autocomplete="given-name" maxlength="60" value="${esc(prefs.name||'')}" placeholder="Enter your name"></label></div>`,`${first?'<button type="button" class="secondary" id="skip-name">Skip for now</button>':'<button type="button" class="secondary" data-close>Cancel</button>'}<button class="primary" type="submit">Save name</button>`,async fd=>{const n=fd.get('name').trim();if(!n)throw Error('Enter your name, or choose Skip for now.');prefs.name=n[0].toLocaleUpperCase()+n.slice(1);await updateProfileName(prefs.name);prefs.namePrompted=true;appearance();close();render()});
  if(first){prefs.namePrompted=true;appearance();$('#skip-name').onclick=close}
}
function filesPage(){return `<div class="grid two-col"><section class="card"><div class="card-head"><h2>Bring your records together</h2><span class="tag">ON THIS DEVICE</span></div><p class="hint">Import an Excel file from Nidhi Android or another Nidhi web export. Review the number of new, duplicate and invalid rows before merging. Your existing records stay.</p><button class="primary" data-import>Import Excel ↑</button><div class="notice">Matching transaction references and matching date, amount, note, category, account and type are skipped. Importing the same unchanged file again adds no duplicate records.</div></section><section class="card"><div class="card-head"><h2>Your ledger, in a file</h2><span class="tag">XLSX</span></div><p class="hint">Create an Android-compatible Excel file with all months and monthly plans. Download it, or use your device’s share menu to choose an available app.</p><button class="primary" data-export>Create & share Excel ↓</button><p class="hint">${generatedFile?'Latest local file: '+esc(new Date(generatedFile.created).toLocaleString()):'No file has been created on this device yet.'}</p>${generatedFile?'<button class="secondary" id="view-generated">Open latest generated file ↗</button>':''}</section></div><section class="card" style="margin-top:20px"><div class="card-head"><h2>Automatic file creation</h2><button class="text-btn" data-page="settings">Details ↗</button></div><p class="hint">${exportPrefs.frequency==='off'?'Daily · always enabled.':'Daily · always enabled. A new file is prepared when Nidhi is unlocked, open and today’s file is due.'}</p><p class="hint">Files generated here remain in browser storage until you download or share them. Keep a saved copy before clearing browser data. Only the latest generated file is kept locally.</p></section>`}
function showExportBanner(){
  $('#export-ready')?.remove();
  if(!generatedFile||localStorage.getItem('nidhi-export-dismissed')===String(generatedFile.created))return;
  const bar=document.createElement('section');bar.id='export-ready';bar.className='notice export-ready';
  bar.innerHTML=`<div><b>Excel file ready</b><small>Created ${esc(new Date(generatedFile.created).toLocaleString())}. Download or share to keep an external copy.</small></div><button class="secondary" id="view-generated">Open file ↗</button><button class="text-btn" id="dismiss-export" aria-label="Dismiss file reminder">✕</button>`;
  $('#content').before(bar);
  bar.querySelector('#dismiss-export').onclick=()=>{localStorage.setItem('nidhi-export-dismissed',String(generatedFile.created));bar.remove()};
}
function openExport(entry){
  const file=new File([entry.blob],entry.name,{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'});
  const shareable=!!navigator.share&&!!navigator.canShare&&navigator.canShare({files:[file]});
  modal(`<h2>Your Excel file is ready</h2><p>${esc(entry.name)}</p><div class="summary-strip"><div class="card"><small>Records</small><b>${entry.count}</b></div><div class="card"><small>Duplicates omitted</small><b>${entry.duplicates||0}</b></div><div class="card"><small>File size</small><b>${Math.max(1,Math.ceil(file.size/1024))} KB</b></div></div><p>Includes all months and your monthly plan. ${shareable?'Share opens your device’s available file-sharing apps.':'This browser cannot share XLSX files directly. Download the file, then attach it in WhatsApp, email or another app.'}</p><p class="hint">This file is not encrypted. Choose your recipients carefully.</p>`,`<button class="secondary" type="button" id="download-file">Download XLSX ↓</button>${shareable?'<button class="primary" type="button" id="share-file">Share file ↗</button>':''}`);
  $('#download-file').onclick=()=>{const url=URL.createObjectURL(file),a=document.createElement('a');a.href=url;a.download=file.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);toast('Download requested — check your browser’s Downloads.')};
  if(shareable)$('#share-file').onclick=async()=>{try{await navigator.share({files:[file]});toast('Share request handed to your device.')}catch(e){if(e.name!=='AbortError')$('#modal-error').textContent='File sharing is unavailable. Download the XLSX and attach it in your chosen app.'}};
}
async function createExcelEntry(){
  if(!state.transactions.length&&!state.budget.commitments.length&&!state.budget.incomeSources.length&&!state.budget.plans.length)throw Error('Add records or a monthly plan before creating an Excel file.');
  const result=deduplicated(state),blob=await writeExcel(result.next),created=Date.now();
  const stamp=new Date(created).toISOString().replace(/[:.]/g,'-');
  return {blob,name:`nidhi_${stamp}.xlsx`,created,count:result.next.transactions.length,duplicates:result.duplicates};
}
async function exportExcel(){const entry=await createExcelEntry();await saveGeneratedExport(entry);generatedFile=entry;if(['daily','weekly','monthly'].includes(exportPrefs.frequency)){exportPrefs.lastPeriod=exportPrefs.frequency+':'+periodId(exportPrefs.frequency);localStorage.setItem('nidhi-export-prefs',JSON.stringify(exportPrefs));}showExportBanner();openExport(entry)}
async function checkScheduledExport(){
  if(!state||document.visibilityState!=='visible'||busy||exportRunning||!['daily','weekly','monthly'].includes(exportPrefs.frequency))return;
  const period=exportPrefs.frequency+':'+periodId(exportPrefs.frequency);
  if(exportPrefs.lastPeriod===period&&generatedFile)return;
  if(!state.transactions.length&&!state.budget.commitments.length&&!state.budget.incomeSources.length&&!state.budget.plans.length)return;
  exportRunning=true;
  try{const entry=await createExcelEntry();await saveGeneratedExport(entry);generatedFile=entry;exportPrefs.lastPeriod=period;localStorage.setItem('nidhi-export-prefs',JSON.stringify(exportPrefs));showExportBanner();if(page==='files')render();toast('Scheduled Excel file prepared. Download or share it when ready.')}catch(e){toast('Could not create the scheduled Excel file: '+e.message)}finally{exportRunning=false}
}
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')checkScheduledExport()});

let reminderStarted=false;
async function unlocked(name){
 prefs.name=name;appearance();state=await load();assertSession();
 if(!navigationReady||leavingApp){
  const launch=new URL(location.href),shortcut=launch.searchParams.get('launch');
  page=launch.hash==='#notifications'?'notifications':['history','plan','qr'].includes(shortcut)?shortcut:'home';
  launch.searchParams.delete('launch');window.history.replaceState(window.history.state,'',launch.pathname+launch.search+'#'+page);
 }
 initializeNavigation(page);render();await carry(true);
 generatedFile=await loadGeneratedExport();showExportBanner();
 if(!reminderStarted){await initReminders({getState:()=>state,toast,render});reminderStarted=true}else await resumeReminders();
 await checkScheduledExport();if(page==='notifications')render();
}
function hidePrivateScreen(){
 lastHomeBack=0;window.dispatchEvent(new Event('nidhi-lock'));stopQr();state=null;generatedFile=null;pauseReminderMessages();
 $('#content').innerHTML='';$('#export-ready')?.remove();$('#reminder-inbox')?.remove();$('#modal').close();$('#modal-body').innerHTML='';$('#modal-actions').innerHTML='';$('#modal-form').onsubmit=null;$('#toast').style.display='none';
}
try{await startAuth({unlock:unlocked,lock:hidePrivateScreen});setInterval(checkScheduledExport,60000)}catch(e){$('#auth-gate').hidden=false;$('#auth-gate').textContent='Unable to open local storage: '+e.message+'. Your existing records have not been erased.'}
window.addEventListener('nidhi-unlock',()=>{if(pendingImportFile){const file=pendingImportFile;pendingImportFile=null;importChosenFile(file);return}if(!localStorage.getItem('nidhi-pwa-tour-seen'))showTour()});
function showTour(){
 const steps=[['Welcome to Nidhi','Your name and six-digit PIN are now set. The app locks whenever it opens or comes back to the screen. The ledger stays local; a forgotten PIN cannot be recovered.'],['Your daily view','Home shows your recorded income, expenses, balance and daily spending allowance. Add income and commitments in Monthly plan to plan ahead.'],['Add and understand','Use the Add button, category/account dropdowns, History and Analyze. Analysis and what-if targets never edit transactions.'],['A daily Excel copy','Daily Excel preparation is always enabled while the app is unlocked and open. Download or share the prepared file to keep a copy outside this browser. A closed PWA cannot reliably save files on a timer.'],['Transfer with QR','Open QR Transfer on Android or the PWA. The sender selects a date range and displays complete record batches with Next/Back controls. The receiver scans each code to import it and sees completed-page progress. Duplicates are skipped. QR data is unencrypted; show it only to your recipient.']];
 let index=0;localStorage.setItem('nidhi-pwa-tour-seen','true');
 function step(){if(!isUnlocked())return;modal(`<span class="eyebrow">QUICK TOUR · ${index+1} / ${steps.length}</span><h2>${steps[index][0]}</h2><p>${steps[index][1]}</p>`,`<button class="secondary" type="button" data-close>Skip tour</button><button class="primary" id="tour-next" type="button">${index===steps.length-1?'Start using Nidhi':'Next'}</button>`);$('#tour-next').onclick=()=>{close();index++;if(index<steps.length)step()}}
 step();
}
