document.addEventListener('change',e=>{if(e.target.id==='note-choice'&&e.target.value){document.querySelector('#modal-form [name=note]').value=displayName(e.target.value)}});

const monthInput=$('#month');monthInput.hidden=true;const monthDisplay=document.createElement('button');monthDisplay.id='month-display';monthDisplay.type='button';monthDisplay.className='secondary';monthDisplay.textContent=new Date(selected+'-01T12:00').toLocaleDateString('en-IN',{month:'long',year:'numeric'})+' ▾';monthInput.after(monthDisplay);
monthDisplay.onclick=()=>{const [year,month]=selected.split('-').map(Number);const years=[...new Set([year,new Date().getFullYear(),...state.transactions.map(t=>new Date(t.dateTime).getFullYear())])].sort((a,b)=>b-a);modal('<h2>Choose month</h2><div class="fields two-col"><label>Month<select name="month">'+Array.from({length:12},(_,i)=>'<option value="'+String(i+1).padStart(2,'0')+'" '+(month===i+1?'selected':'')+'>'+new Date(2020,i,1).toLocaleDateString('en-IN',{month:'long'})+'</option>').join('')+'</select></label><label>Year<input name="year" type="number" min="1900" max="9999" value="'+year+'" required></label></div>','<button class="secondary" type="button" data-close>Close</button><button class="primary" type="submit">Apply</button>',async fd=>{const y=Number(fd.get('year'));if(!Number.isInteger(y)||y<1900||y>9999)throw Error('Enter a valid year.');selected=y+'-'+fd.get('month');monthInput.value=selected;close();render();await task(()=>carry(true))})};
